#import "ADDiscordPlugin.h"
#import "ADDiscordService.h"
#import <Adium/ESDebugAILog.h>
#import <glib.h>

// Generated by PURPLE_INIT_PLUGIN(discord, ...) in libdiscord.c when built without PURPLE_PLUGINS
extern gboolean purple_init_discord_plugin(void);

@implementation ADDiscordPlugin

- (void)installPlugin
{
	[ADDiscordService registerService];
}

- (void)uninstallPlugin
{
}

// Called while libpurple's core is initializing, alongside Adium's built-in protocols
- (void)installLibpurplePlugin
{
	purple_init_discord_plugin();
}

- (void)loadLibpurplePlugin
{
	AILog(@"Discord for Adium %@ loaded", [self pluginVersion]);
}

- (NSString *)pluginAuthor      { return @"Eion Robb (purple-discord), Adium port contributors"; }
- (NSString *)pluginDescription { return @"Discord protocol support, based on purple-discord."; }
- (NSString *)pluginURL         { return @"https://github.com/EionRobb/purple-discord"; }
- (NSString *)pluginVersion
{
	return [[[NSBundle bundleForClass:[self class]] infoDictionary] objectForKey:@"CFBundleShortVersionString"];
}

@end
